import base64,os,subprocess,ast
code=base64.b64decode("").decode("utf-8")
ast.parse(code)
open("/content/fly/char_loop.py","w",encoding="utf-8").write(code)
print("wrote", len(code))
ps=subprocess.run("ps -eo pid,cmd | grep [c]har_loop.py",shell=True,capture_output=True,text=True).stdout.strip()
print("running:",ps or "(none)")
if not ps:
    subprocess.Popen("nohup python -u /content/fly/char_loop.py > /content/fly/char.log 2>&1 &",shell=True,executable="/bin/bash")
    print("LAUNCHED")
